import { type NextRequest, NextResponse } from 'next/server';
import { getContentSecurityPolicy } from '@/lib/csp';
import { matchesConfiguredPath } from '@/lib/match-configured-path';

export const config = {
  matcher: '/:path*',
};

const TRACKER_PATH = '/script.js';
const RECORDER_PATH = '/recorder.js';
const COLLECT_PATH = '/api/send';
const LOGIN_PATH = '/login';
const BASE_PATH = process.env.BASE_PATH || '';

const apiHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Allow-Methods': 'GET, DELETE, POST, PUT',
  'Access-Control-Max-Age': process.env.CORS_MAX_AGE || '86400',
  'Cache-Control': 'no-cache',
};

const trackerHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Cache-Control': 'public, max-age=86400, must-revalidate',
};

// Resolved once at startup — env vars don't change after the process starts.
const contentSecurityPolicy = getContentSecurityPolicy();

function customCollectEndpoint(request: NextRequest) {
  const collectEndpoint = process.env.COLLECT_API_ENDPOINT;

  if (collectEndpoint) {
    const url = request.nextUrl.clone();

    if (matchesConfiguredPath(url.pathname, collectEndpoint, BASE_PATH)) {
      url.pathname = COLLECT_PATH;
      return NextResponse.rewrite(url, { headers: apiHeaders });
    }
  }
}

function customScriptName(request: NextRequest) {
  const scriptName = process.env.TRACKER_SCRIPT_NAME;

  if (scriptName) {
    const url = request.nextUrl.clone();
    const names = scriptName.split(',').map(name => name.trim().replace(/^\/+/, ''));

    if (names.find(name => matchesConfiguredPath(url.pathname, name, BASE_PATH))) {
      url.pathname = TRACKER_PATH;
      return NextResponse.rewrite(url, { headers: trackerHeaders });
    }
  }
}

function customScriptUrl(request: NextRequest) {
  const scriptUrl = process.env.TRACKER_SCRIPT_URL;

  if (scriptUrl && matchesConfiguredPath(request.nextUrl.pathname, TRACKER_PATH, BASE_PATH)) {
    return NextResponse.rewrite(scriptUrl, { headers: trackerHeaders });
  }
}

function applyStaticScriptHeaders(request: NextRequest, response: NextResponse) {
  if (
    matchesConfiguredPath(request.nextUrl.pathname, TRACKER_PATH, BASE_PATH) ||
    matchesConfiguredPath(request.nextUrl.pathname, RECORDER_PATH, BASE_PATH)
  ) {
    Object.entries(trackerHeaders).forEach(([key, value]) => {
      response.headers.set(key, value);
    });
  }
}

function disableLogin(request: NextRequest) {
  const loginDisabled = process.env.DISABLE_LOGIN;

  if (loginDisabled && matchesConfiguredPath(request.nextUrl.pathname, LOGIN_PATH, BASE_PATH)) {
    return new NextResponse('Access denied', { status: 403 });
  }
}

export default function middleware(req: NextRequest) {
  const fns = [customCollectEndpoint, customScriptName, customScriptUrl, disableLogin];

  let res: NextResponse | undefined;

  for (const fn of fns) {
    res = fn(req);
    if (res) {
      break;
    }
  }

  res ??= NextResponse.next();
  applyStaticScriptHeaders(req, res);

  // Set the CSP here, not only at build time in next.config.ts, so
  // ALLOWED_FRAME_URLS is resolved from the runtime environment.
  res.headers.set('Content-Security-Policy', contentSecurityPolicy);

  return res;
}

import 'dotenv/config';
import createNextIntlPlugin from 'next-intl/plugin';
import pkg from './package.json' with { type: 'json' };
import { getContentSecurityPolicy } from './src/lib/csp';

const withNextIntl = createNextIntlPlugin('./src/i18n/request.ts');

const TRACKER_SCRIPT = '/script.js';
const RECORDER_SCRIPT = '/recorder.js';

const isProd = process.env.NODE_ENV === 'production';
const isVercel = Boolean(process.env.VERCEL);

const apiUrl = process.env.API_URL || '';
const basePath = process.env.BASE_PATH || '';
const cloudMode = process.env.CLOUD_MODE || '';
const cloudUrl = process.env.CLOUD_URL || '';
const collectApiEndpoint = process.env.COLLECT_API_ENDPOINT || '';
const corsMaxAge = process.env.CORS_MAX_AGE || '';
const defaultCurrency = process.env.DEFAULT_CURRENCY || '';
const defaultLocale = process.env.DEFAULT_LOCALE || '';
const forceSSL = process.env.FORCE_SSL || '';
const trackerScriptName = process.env.TRACKER_SCRIPT_NAME || '';
const trackerScriptURL = process.env.TRACKER_SCRIPT_URL || '';
const selfTrack = process.env.UMAMI_SELF_TRACK || '';
const selfRecord = process.env.UMAMI_SELF_RECORD || '';

function isRelativeUrl(url: string) {
  return Boolean(url && !/^https?:\/\//i.test(url));
}

function normalizePath(url: string) {
  return `/${url.replace(/^\/+|\/+$/g, '')}`;
}

const defaultHeaders = [
  {
    key: 'X-DNS-Prefetch-Control',
    value: 'on',
  },
  {
    key: 'Content-Security-Policy',
    value: getContentSecurityPolicy(),
  },
];

if (forceSSL) {
  defaultHeaders.push({
    key: 'Strict-Transport-Security',
    value: 'max-age=63072000; includeSubDomains; preload',
  });
}

const trackerHeaders = [
  {
    key: 'Access-Control-Allow-Origin',
    value: '*',
  },
  {
    key: 'Cache-Control',
    value: 'public, max-age=86400, must-revalidate',
  },
];

const apiHeaders = [
  {
    key: 'Access-Control-Allow-Origin',
    value: '*',
  },
  {
    key: 'Access-Control-Allow-Headers',
    value: '*',
  },
  {
    key: 'Access-Control-Allow-Methods',
    value: 'GET, DELETE, POST, PUT',
  },
  {
    key: 'Access-Control-Max-Age',
    value: corsMaxAge || '86400',
  },
  {
    key: 'Cache-Control',
    value: 'no-cache',
  },
];

const headers = [
  {
    source: '/api/:path*',
    headers: apiHeaders,
  },
  {
    source: '/:path*',
    headers: defaultHeaders,
  },
];

if (isProd) {
  headers.push({
    source: TRACKER_SCRIPT,
    headers: trackerHeaders,
  });
  headers.push({
    source: RECORDER_SCRIPT,
    headers: trackerHeaders,
  });
}

const rewrites = [];

if (trackerScriptURL) {
  rewrites.push({
    source: TRACKER_SCRIPT,
    destination: trackerScriptURL,
  });
}

if (collectApiEndpoint) {
  headers.push({
    source: collectApiEndpoint,
    headers: apiHeaders,
  });

  rewrites.push({
    source: collectApiEndpoint,
    destination: '/api/send',
  });
}

if (isRelativeUrl(apiUrl)) {
  const normalizedApiUrl = normalizePath(apiUrl);

  if (normalizedApiUrl !== '/' && normalizedApiUrl !== '/api') {
    headers.push({
      source: `${normalizedApiUrl}/:path*`,
      headers: apiHeaders,
    });

    rewrites.push({
      source: `${normalizedApiUrl}/:path*`,
      destination: '/api/:path*',
    });
  }
}

const redirects = [
  {
    source: '/teams/:id/dashboard/edit',
    destination: '/dashboard/edit',
    permanent: false,
  },
  {
    source: '/teams/:id/dashboard',
    destination: '/dashboard',
    permanent: false,
  },
  {
    source: '/settings',
    destination: '/settings/preferences',
    permanent: false,
  },
  {
    source: '/teams/:id',
    destination: '/teams/:id/websites',
    permanent: false,
  },
  {
    source: '/teams/:id/settings',
    destination: '/teams/:id/settings/preferences',
    permanent: false,
  },
  {
    source: '/admin',
    destination: '/admin/users',
    permanent: false,
  },
];

// Adding rewrites + headers for all alternative tracker script names.
if (trackerScriptName) {
  const names = trackerScriptName?.split(',').map(name => name.trim());

  if (names) {
    names.forEach(name => {
      const normalizedSource = `/${name.replace(/^\/+/, '')}`;

      rewrites.push({
        source: normalizedSource,
        destination: TRACKER_SCRIPT,
      });

      headers.push({
        source: normalizedSource,
        headers: trackerHeaders,
      });
    });
  }
}

if (isProd && cloudMode) {
  rewrites.push({
    source: '/script.js',
    destination: 'https://cloud.umami.is/script.js',
  });
}

/** @type {import('next').NextConfig} */
export default withNextIntl({
  reactStrictMode: false,
  devIndicators: {
    position: 'bottom-right',
  },
  env: {
    apiUrl,
    basePath,
    cloudMode,
    cloudUrl,
    currentVersion: pkg.version,
    defaultCurrency,
    defaultLocale,
    selfTrack,
    selfRecord,
  },
  basePath,
  output: isVercel ? undefined : 'standalone',
  typescript: {
    ignoreBuildErrors: true,
  },
  experimental: {
    useTypeScriptCli: true,
  },
  async headers() {
    return headers;
  },
  async rewrites() {
    return [
      ...rewrites,
      // Preserve legacy report requests outside the published API contract.
      {
        source: '/api/reports/:path*',
        destination: '/compat/api/reports/:path*',
      },
      {
        source: '/api/websites/:websiteId/reports',
        destination: '/compat/api/websites/:websiteId/reports',
      },
      {
        source: '/telemetry.js',
        destination: '/api/scripts/telemetry',
      },
      {
        source: '/teams/:teamId/:path*',
        destination: '/:path*',
      },
    ];
  },
  async redirects() {
    return [...redirects];
  },
});

import { describe, expect, test } from 'vitest';
import { UmamiClient } from './client';
import { operations } from './generated/operations';

interface Captured {
  url: URL;
  method: string;
  headers: Record<string, string>;
  body?: string;
}

function createClient(response: unknown = {}, options: Record<string, unknown> = {}) {
  const calls: Captured[] = [];
  const client = new UmamiClient({
    baseUrl: 'https://example.com/api',
    token: 'token',
    ...options,
    fetch: async (url, init) => {
      calls.push({
        url: new URL(url.toString()),
        method: init?.method ?? 'GET',
        headers: init?.headers as Record<string, string>,
        body: init?.body as string | undefined,
      });

      return new Response(JSON.stringify(response), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    },
  });

  return { client, calls };
}

describe('UmamiClient', () => {
  test('exposes a method for every generated operation', () => {
    const client = new UmamiClient({ fetch: async () => new Response('{}') });

    for (const operationId of Object.keys(operations)) {
      expect(typeof (client as unknown as Record<string, unknown>)[operationId]).toBe('function');
    }
  });

  test('builds GET requests with path and query parameters', async () => {
    const { client, calls } = createClient({ pageviews: 1 });

    await client.getWebsiteStats({ websiteId: 'w1', startAt: 1, endAt: 2, browser: 'chrome' });

    expect(calls[0].method).toBe('GET');
    expect(calls[0].url.pathname).toBe('/api/websites/w1/stats');
    expect(calls[0].url.searchParams.get('startAt')).toBe('1');
    expect(calls[0].url.searchParams.get('browser')).toBe('chrome');
    expect(calls[0].headers.authorization).toBe('Bearer token');
  });

  test('supports the legacy positional signature', async () => {
    const { client, calls } = createClient([]);

    await client.getWebsiteMetrics('w1', { startAt: 1, endAt: 2, type: 'url' });
    await client.getWebsiteSession('w1', 's1');

    expect(calls[0].url.pathname).toBe('/api/websites/w1/metrics');
    expect(calls[0].url.searchParams.get('type')).toBe('url');
    expect(calls[1].url.pathname).toBe('/api/websites/w1/sessions/s1');
  });

  test('sends JSON bodies for POST operations', async () => {
    const { client, calls } = createClient([]);

    await client.createWebsiteFunnel({
      websiteId: 'w1',
      name: 'Signup funnel',
      parameters: { window: 60, steps: [] },
    });

    expect(calls[0].method).toBe('POST');
    expect(calls[0].url.pathname).toBe('/api/websites/w1/funnels');
    expect(JSON.parse(calls[0].body as string)).toEqual({
      name: 'Signup funnel',
      parameters: { window: 60, steps: [] },
    });
  });

  test('sends structured funnel criteria through the GET stats API', async () => {
    const { client, calls } = createClient([]);
    const steps = [
      { type: 'path', value: '/a?x=1&y=日本語' },
      { type: 'event', value: 'signup' },
    ];
    await client.getWebsiteFunnelStats({
      websiteId: 'w1',
      startAt: 1,
      endAt: 2,
      window: 60,
      steps: JSON.stringify(steps),
      browser1: 'eq.Chrome',
    });
    expect(calls[0].method).toBe('GET');
    expect(calls[0].body).toBeUndefined();
    expect(calls[0].url.pathname).toBe('/api/websites/w1/funnels/stats');
    expect(JSON.parse(calls[0].url.searchParams.get('steps') ?? 'null')).toEqual(steps);
    expect(calls[0].url.searchParams.get('browser1')).toBe('eq.Chrome');
  });

  test('uses the Cloud base URL and API key header by default', async () => {
    const calls: Captured[] = [];
    const client = new UmamiClient({
      apiKey: 'api-key',
      fetch: async (url, init) => {
        calls.push({
          url: new URL(url.toString()),
          method: init?.method ?? 'GET',
          headers: init?.headers as Record<string, string>,
        });
        return new Response('{"data":[]}', { headers: { 'content-type': 'application/json' } });
      },
    });

    await client.listWebsites();

    expect(calls[0].url.toString()).toBe('https://api.umami.is/v1/websites');
    expect(calls[0].headers['x-umami-api-key']).toBe('api-key');
  });

  test('merges custom and per-request headers', async () => {
    const { client, calls } = createClient({}, { headers: { 'x-a': '1' } });

    await client.getMe(undefined, { headers: { 'x-b': '2' } });

    expect(calls[0].headers).toMatchObject({ 'x-a': '1', 'x-b': '2' });
  });

  test('withToken returns a client using the new token', async () => {
    const { client, calls } = createClient({});

    await client.withToken('other').getMe();

    expect(calls[0].headers.authorization).toBe('Bearer other');
  });

  test('call() invokes any operation by id', async () => {
    const { client, calls } = createClient({ visitors: 3 });

    const result = await client.call('getWebsiteActive', { websiteId: 'w1' });

    expect(result).toEqual({ visitors: 3 });
    expect(calls[0].url.pathname).toBe('/api/websites/w1/active');
  });
});
